\set ON_ERROR_STOP on
DO $$ BEGIN
IF (SELECT count(*) FROM blobs) <> 2 THEN RAISE EXCEPTION 'Blob count mismatch'; END IF;
IF NOT EXISTS (SELECT 1 FROM blobs WHERE key = 'notes/hello.txt' AND data = decode('557064617465642053746f726542656e6368210a', 'hex') AND content_type = 'text/plain' AND owner_name = 'storebench') THEN RAISE EXCEPTION 'Blob mismatch: notes/hello.txt'; END IF;
IF NOT EXISTS (SELECT 1 FROM blobs WHERE key = 'images/pattern.bin' AND data = decode('', 'hex') AND content_type = 'application/octet-stream' AND owner_name = 'storebench') THEN RAISE EXCEPTION 'Blob mismatch: images/pattern.bin'; END IF;
IF (SELECT substring(data FROM 101 FOR 100) FROM blobs WHERE key = 'images/pattern.bin') <> decode('d9ad263cec85ad5a4291da464a2d35e5dd872d395985c7685a2fab624af17af7d9ad263cec85ad5a4291da464a2d35e5dd872d395985c7685a2fab624af17af7d9ad263cec85ad5a4291da464a2d35e5dd872d395985c7685a2fab624af17af7d9ad263c', 'hex') THEN RAISE EXCEPTION 'Range mismatch'; END IF;
END $$;
SELECT 'PostgreSQL blob check passed' AS result;
